import { sql } from "drizzle-orm"
import { boolean, customType, text, timestamp, uuid } from "drizzle-orm/pg-core"

// Column types for extensions created by docker/postgres/initdb/02-database.sql.
export const citext = customType<{ data: string }>({ dataType: () => "citext" })
export const ltree = customType<{ data: string }>({ dataType: () => "ltree" })
export const tsvector = customType<{ data: string }>({
  dataType: () => "tsvector",
})

/** Time-ordered UUID primary key generated by PostgreSQL 18 (doc/02 §7). */
export const primaryId = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`)

export const timestamptz = () => timestamp({ withTimezone: true })

export const seoColumns = () => ({
  seoTitle: text(),
  seoDescription: text(),
  noindex: boolean().notNull().default(false),
})

export const timestamps = () => ({
  createdAt: timestamptz().notNull().defaultNow(),
  updatedAt: timestamptz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
})
